+bool is_pinned_cpu_tensor(const torch::stable::Tensor& tensor) {
+  cudaPointerAttributes attributes{};
+  const auto status =
+      cudaPointerGetAttributes(&attributes, tensor.const_data_ptr());
+  if (status != cudaSuccess) {
